"use client"

import { useState } from "react"
import Link from "next/link"
import { useRouter } from "next/navigation"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Separator } from "@/components/ui/separator"
import {
  ArrowLeft,
  FileText,
  ListOrdered,
  AlignLeft,
  BookOpen,
  ImageIcon,
  ImagePlus,
  Copy,
  Check,
  Sparkles,
  RefreshCw,
  Download,
  Save,
  Plus,
  Loader2,
} from "lucide-react"
import { toast } from "sonner"

type Project = {
  id: string
  productName: string
  category: string | null
  features: string | null
  sellingPoints: string | null
  keywords: string | null
  useScenario: string | null
  targetAudience: string | null
  priceRange: string | null
  brandTone: string | null
  platform: string
  language: string
  createdAt: Date
  updatedAt: Date
  records: Array<{
    id: string
    contentType: string
    content: string | null
    imageUrl: string | null
    prompt: string | null
    createdAt: Date
  }>
}

const platformLabels: Record<string, string> = {
  amazon: "Amazon",
  shopify: "Shopify",
  tiktok: "TikTok Shop",
}

const languageLabels: Record<string, string> = {
  zh: "中文",
  en: "English",
  es: "Español",
}

const contentTypeInfo: Record<
  string,
  {
    label: string
    icon: React.ComponentType<{ className?: string }>
    color: string
    bgColor: string
    type: "copy" | "image"
  }
> = {
  title: {
    label: "商品标题",
    icon: FileText,
    color: "text-blue-600 dark:text-blue-400",
    bgColor: "bg-blue-50 dark:bg-blue-950/30",
    type: "copy",
  },
  bulletPoints: {
    label: "要点描述",
    icon: ListOrdered,
    color: "text-emerald-600 dark:text-emerald-400",
    bgColor: "bg-emerald-50 dark:bg-emerald-950/30",
    type: "copy",
  },
  shortDesc: {
    label: "短描述",
    icon: AlignLeft,
    color: "text-violet-600 dark:text-violet-400",
    bgColor: "bg-violet-50 dark:bg-violet-950/30",
    type: "copy",
  },
  longDesc: {
    label: "长描述",
    icon: BookOpen,
    color: "text-amber-600 dark:text-amber-400",
    bgColor: "bg-amber-50 dark:bg-amber-950/30",
    type: "copy",
  },
  mainImage: {
    label: "商品主图",
    icon: ImageIcon,
    color: "text-pink-600 dark:text-pink-400",
    bgColor: "bg-pink-50 dark:bg-pink-950/30",
    type: "image",
  },
  sceneImage: {
    label: "场景图",
    icon: ImagePlus,
    color: "text-cyan-600 dark:text-cyan-400",
    bgColor: "bg-cyan-50 dark:bg-cyan-950/30",
    type: "image",
  },
}

export function ResultsView({ project }: { project: Project }) {
  const router = useRouter()
  const [regenerating, setRegenerating] = useState<string | null>(null)
  const [records, setRecords] = useState(project.records)
  const [copiedId, setCopiedId] = useState<string | null>(null)

  async function handleCopy(content: string | null, recordId: string) {
    if (!content) return
    await navigator.clipboard.writeText(content)
    setCopiedId(recordId)
    setTimeout(() => setCopiedId(null), 2000)
    toast.success("已复制到剪贴板")
  }

  async function handleRegenerate(contentType: string) {
    setRegenerating(contentType)

    try {
      const res = await fetch("/api/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          projectId: project.id,
          contentType,
        }),
      })

      const data = await res.json()
      if (!res.ok) throw new Error(data.error)

      setRecords((prev) => [data.record, ...prev])
      toast.success(
        `${contentTypeInfo[contentType]?.label || contentType} 重新生成成功！`
      )
    } catch {
      toast.error("生成失败，请稍后再试")
    } finally {
      setRegenerating(null)
    }
  }

  async function handleExportAll() {
    const text = records
      .filter((r) => r.content)
      .map((r) => {
        const label = contentTypeInfo[r.contentType]?.label || r.contentType
        return `【${label}】\n${r.content}\n`
      })
      .join("\n---\n\n")

    if (!text) {
      toast.error("暂无内容可导出")
      return
    }

    await navigator.clipboard.writeText(text)
    toast.success("全部内容已复制到剪贴板")
  }

  function handleSaveToHistory() {
    toast.success("已保存到历史记录")
  }

  const getLatestRecord = (contentType: string) => {
    return records.find((r) => r.contentType === contentType)
  }

  const copyTypes = ["title", "bulletPoints", "shortDesc", "longDesc"]
  const imageTypes = ["mainImage", "sceneImage"]

  return (
    <div className="min-h-screen bg-gradient-to-b from-background to-muted/20">
      {/* Header */}
      <div className="border-b bg-background/80 backdrop-blur-sm sticky top-0 z-10">
        <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <Link
                href={`/dashboard/${project.id}`}
                className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground transition-colors"
              >
                <ArrowLeft className="size-4" />
                返回项目
              </Link>
              <Separator orientation="vertical" className="h-5" />
              <div>
                <h1 className="text-lg font-semibold tracking-tight">
                  {project.productName}
                </h1>
                <div className="flex items-center gap-2 mt-0.5">
                  <Badge variant="secondary" className="text-xs">
                    {platformLabels[project.platform] || project.platform}
                  </Badge>
                  <span className="text-xs text-muted-foreground">
                    {languageLabels[project.language] || project.language}
                  </span>
                </div>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <Button variant="outline" size="sm" onClick={handleExportAll}>
                <Download className="size-4 mr-1.5" />
                导出全部
              </Button>
              <Button size="sm" onClick={handleSaveToHistory}>
                <Save className="size-4 mr-1.5" />
                保存记录
              </Button>
            </div>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-8">
        {/* Summary */}
        {records.length > 0 && (
          <div className="flex flex-wrap gap-3 mb-8">
            <span className="text-sm text-muted-foreground">
              已生成 {records.length} 项内容
            </span>
            <span className="text-xs text-muted-foreground">·</span>
            <span className="text-sm text-muted-foreground">
              平台：{platformLabels[project.platform] || project.platform}
            </span>
            <span className="text-xs text-muted-foreground">·</span>
            <span className="text-sm text-muted-foreground">
              语言：{languageLabels[project.language] || project.language}
            </span>
          </div>
        )}

        <div className="grid gap-8 lg:grid-cols-2">
          {/* Copy Results - Left */}
          <div>
            <div className="flex items-center gap-2 mb-5">
              <div className="flex size-7 items-center justify-center rounded-md bg-primary/10">
                <FileText className="size-4 text-primary" />
              </div>
              <h2 className="text-lg font-semibold">文案结果</h2>
            </div>

            {copyTypes.map((type) => {
              const info = contentTypeInfo[type]
              if (!info) return null
              const Icon = info.icon
              const record = getLatestRecord(type)

              return (
                <Card
                  key={type}
                  className={`mb-4 border-l-4 overflow-hidden ${
                    record ? "" : "opacity-50"
                  }`}
                  style={{
                    borderLeftColor: record
                      ? `var(--${type === "title" ? "blue" : type === "bulletPoints" ? "emerald" : type === "shortDesc" ? "violet" : "amber"}-500)`
                      : undefined,
                  }}
                >
                  <CardHeader className="pb-3">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <Icon className={`size-5 ${info.color}`} />
                        <CardTitle className="text-sm">{info.label}</CardTitle>
                      </div>
                      <div className="flex items-center gap-1">
                        {record && (
                          <>
                            <Button
                              variant="ghost"
                              size="icon-sm"
                              onClick={() =>
                                handleCopy(record.content, record.id)
                              }
                              title="复制"
                            >
                              {copiedId === record.id ? (
                                <Check className="size-4 text-emerald-500" />
                              ) : (
                                <Copy className="size-4" />
                              )}
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon-sm"
                              onClick={() => handleRegenerate(type)}
                              disabled={regenerating !== null}
                              title="重新生成"
                            >
                              {regenerating === type ? (
                                <Loader2 className="size-4 animate-spin" />
                              ) : (
                                <RefreshCw className="size-4" />
                              )}
                            </Button>
                          </>
                        )}
                        {!record && (
                          <Button
                            variant="ghost"
                            size="icon-sm"
                            onClick={() => handleRegenerate(type)}
                            disabled={regenerating !== null}
                            title="生成"
                          >
                            {regenerating === type ? (
                              <Loader2 className="size-4 animate-spin" />
                            ) : (
                              <Sparkles className="size-4" />
                            )}
                          </Button>
                        )}
                      </div>
                    </div>
                  </CardHeader>
                  <CardContent>
                    {record?.content ? (
                      <div className="rounded-lg bg-muted/30 p-4">
                        <pre className="whitespace-pre-wrap text-sm font-sans leading-relaxed">
                          {record.content}
                        </pre>
                      </div>
                    ) : (
                      <div className="rounded-lg bg-muted/10 p-6 text-center">
                        <p className="text-sm text-muted-foreground">
                          暂未生成{info.label}
                        </p>
                        <Button
                          variant="outline"
                          size="sm"
                          className="mt-2"
                          onClick={() => handleRegenerate(type)}
                          disabled={regenerating !== null}
                        >
                          <Sparkles className="size-3.5 mr-1.5" />
                          立即生成
                        </Button>
                      </div>
                    )}
                  </CardContent>
                </Card>
              )
            })}
          </div>

          {/* Image Results - Right */}
          <div>
            <div className="flex items-center gap-2 mb-5">
              <div className="flex size-7 items-center justify-center rounded-md bg-primary/10">
                <ImageIcon className="size-4 text-primary" />
              </div>
              <h2 className="text-lg font-semibold">图片结果</h2>
            </div>

            {imageTypes.map((type) => {
              const info = contentTypeInfo[type]
              if (!info) return null
              const Icon = info.icon
              const record = getLatestRecord(type)

              return (
                <Card
                  key={type}
                  className={`mb-4 border-l-4 overflow-hidden ${
                    record ? "" : "opacity-50"
                  }`}
                  style={{
                    borderLeftColor: record
                      ? `var(--${type === "mainImage" ? "pink" : "cyan"}-500)`
                      : undefined,
                  }}
                >
                  <CardHeader className="pb-3">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <Icon className={`size-5 ${info.color}`} />
                        <CardTitle className="text-sm">{info.label}</CardTitle>
                      </div>
                      <div className="flex items-center gap-1">
                        {record && (
                          <>
                            <Button
                              variant="ghost"
                              size="icon-sm"
                              onClick={() =>
                                record.prompt &&
                                handleCopy(record.prompt, `prompt-${record.id}`)
                              }
                              title="复制提示词"
                            >
                              {copiedId === `prompt-${record.id}` ? (
                                <Check className="size-4 text-emerald-500" />
                              ) : (
                                <Copy className="size-4" />
                              )}
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon-sm"
                              onClick={() => handleRegenerate(type)}
                              disabled={regenerating !== null}
                              title="重新生成"
                            >
                              {regenerating === type ? (
                                <Loader2 className="size-4 animate-spin" />
                              ) : (
                                <RefreshCw className="size-4" />
                              )}
                            </Button>
                          </>
                        )}
                        {!record && (
                          <Button
                            variant="ghost"
                            size="icon-sm"
                            onClick={() => handleRegenerate(type)}
                            disabled={regenerating !== null}
                            title="生成"
                          >
                            {regenerating === type ? (
                              <Loader2 className="size-4 animate-spin" />
                            ) : (
                              <Sparkles className="size-4" />
                            )}
                          </Button>
                        )}
                      </div>
                    </div>
                  </CardHeader>
                  <CardContent>
                    {record?.imageUrl ? (
                      <div className="aspect-square rounded-lg bg-muted/20 flex items-center justify-center">
                        <p className="text-sm text-muted-foreground">
                          图片预览（待接入真实图片生成API）
                        </p>
                      </div>
                    ) : record?.content ? (
                      <div className="rounded-lg bg-muted/30 p-4">
                        <p className="text-xs text-muted-foreground mb-2">
                          生成的提示词：
                        </p>
                        <pre className="whitespace-pre-wrap text-sm font-sans leading-relaxed">
                          {record.content}
                        </pre>
                      </div>
                    ) : (
                      <div className="rounded-lg bg-muted/10 p-6 text-center">
                        <p className="text-sm text-muted-foreground">
                          暂未生成{info.label}
                        </p>
                        <Button
                          variant="outline"
                          size="sm"
                          className="mt-2"
                          onClick={() => handleRegenerate(type)}
                          disabled={regenerating !== null}
                        >
                          <Sparkles className="size-3.5 mr-1.5" />
                          立即生成
                        </Button>
                      </div>
                    )}

                    {/* Reserved extensions */}
                    {type === "mainImage" && (
                      <div className="mt-3 rounded-lg border border-dashed border-muted-foreground/20 p-3 text-center">
                        <p className="text-xs text-muted-foreground">
                          + Banner 图（预留扩展）
                        </p>
                      </div>
                    )}
                    {type === "sceneImage" && (
                      <div className="mt-3 rounded-lg border border-dashed border-muted-foreground/20 p-3 text-center">
                        <p className="text-xs text-muted-foreground">
                          + 社媒图（预留扩展）
                        </p>
                      </div>
                    )}
                  </CardContent>
                </Card>
              )
            })}
          </div>
        </div>

        {/* Bottom Action Bar */}
        <div className="mt-10 flex flex-wrap items-center justify-center gap-3 rounded-xl border bg-background/50 p-4">
          <Button variant="outline" onClick={() => router.push(`/dashboard/${project.id}`)}>
            <ArrowLeft className="size-4 mr-1.5" />
            继续编辑商品
          </Button>
          <Button variant="outline" onClick={() => router.push("/dashboard/new")}>
            <Plus className="size-4 mr-1.5" />
            新建商品
          </Button>
          <Separator
            orientation="vertical"
            className="h-6 hidden sm:block"
          />
          <Button variant="secondary" onClick={handleSaveToHistory}>
            <Save className="size-4 mr-1.5" />
            保存到历史记录
          </Button>
          <Button variant="default" onClick={handleExportAll}>
            <Download className="size-4 mr-1.5" />
            导出全部内容
          </Button>
        </div>
      </div>
    </div>
  )
}
